def transform(grid):
    """Bridge matching non-background tile colors across blank gutters."""
    out = [row[:] for row in grid]
    counts = Counter(value for row in grid for value in row if value != 0)
    if not counts:
        return out
    frame_color = counts.most_common(1)[0][0]
    inside = Counter(value for row in grid for value in row
                     if value not in (0, frame_color))
    if not inside:
        return out
    common_inside = inside.most_common(1)[0][0]
    bridge_colors = set(inside) - {common_inside}

    # For every color that is not the repeated tile fill, join aligned
    # occurrences in each row and column. Only blank cells are painted, so
    # intervening tiles remain intact.
    height, width = len(grid), len(grid[0])
    for color in bridge_colors:
        for r in range(height):
            positions = [c for c, value in enumerate(grid[r]) if value == color]
            if len(positions) > 1:
                for c in range(positions[0], positions[-1] + 1):
                    if grid[r][c] == 0:
                        out[r][c] = color
        for c in range(width):
            positions = [r for r in range(height) if grid[r][c] == color]
            if len(positions) > 1:
                for r in range(positions[0], positions[-1] + 1):
                    if grid[r][c] == 0:
                        out[r][c] = color
    return out


__all__ = ['transform']


def _check_demo_layout(tile_colors, frame, tile_size, height, width):
    """Build a regular tile example and verify the exact gutter-only result."""
    gap = 1
    grid = [[0] * width for _ in range(height)]
    for tr, row in enumerate(tile_colors):
        for tc, fill in enumerate(row):
            top, left = 1 + tr * (tile_size + gap), 1 + tc * (tile_size + gap)
            for dr in range(tile_size):
                for dc in range(tile_size):
                    r, c = top + dr, left + dc
                    if r < height and c < width:
                        grid[r][c] = frame
            inner = tile_size - 2
            for dr in range(inner):
                for dc in range(inner):
                    r, c = top + 1 + dr, left + 1 + dc
                    if r < height and c < width:
                        grid[r][c] = fill
    got = transform(grid)

    # Independent expected output: preserve tiles and paint only gutter cells
    # located on aligned runs of the marked fills.
    counts = Counter(v for row in grid for v in row if v not in (0, frame))
    dominant = counts.most_common(1)[0][0]
    marked = set(counts) - {dominant}
    expected = [row[:] for row in grid]
    for color in marked:
        for r in range(height):
            pos = [c for c, v in enumerate(grid[r]) if v == color]
            if len(pos) > 1:
                for c in range(pos[0], pos[-1] + 1):
                    if grid[r][c] == 0:
                        expected[r][c] = color
        for c in range(width):
            pos = [r for r in range(height) if grid[r][c] == color]
            if len(pos) > 1:
                for r in range(pos[0], pos[-1] + 1):
                    if grid[r][c] == 0:
                        expected[r][c] = color
    assert got == expected


def _self_test():
    # The two demonstrations' tile-center/fill layouts.
    _check_demo_layout(
        [[4, 4, 3, 3, 4, 4], [4, 1, 4, 4, 1, 4],
         [4, 4, 3, 3, 4, 4], [4, 1, 4, 4, 1, 4],
         [4, 4, 4, 4, 4, 4]],
        frame=2, tile_size=3, height=23, width=28)
    _check_demo_layout(
        [[2, 2, 2, 8, 2, 8], [2, 2, 2, 2, 2, 2],
         [2, 4, 2, 2, 4, 2], [2, 2, 2, 8, 2, 8],
         [2, 4, 2, 2, 4, 2]],
        frame=3, tile_size=4, height=24, width=29)
    return True


if __name__ == '__main__':
    print('demo layout checks passed:', _self_test())
